// Un tablero de depósito INVENTADO: 12 pedidos para preparar, un equipo con capacidad fija.
// Capacidad: 5 unidades de esfuerzo por día. Cada pedido pide entre 3 y 7 unidades.
function azar(semilla) {                       // generador simple y repetible
  let s = semilla;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
}
function simular(limiteWip, semilla) {
  const r = azar(semilla);
  const pedidos = Array.from({ length: 12 }, () => ({ resta: 3 + 4 * r(), ini: null, fin: null }));
  const dt = 0.01, capacidad = 5;
  let t = 0, cola = [...pedidos], enCurso = [];
  while (pedidos.some(p => p.fin === null)) {
    while (enCurso.length < limiteWip && cola.length) { const p = cola.shift(); p.ini = t; enCurso.push(p); }
    const parte = capacidad * dt / enCurso.length;   // el esfuerzo se reparte entre todo lo que está en curso
    for (const p of enCurso) p.resta -= parte;
    t += dt;
    enCurso = enCurso.filter(p => { if (p.resta <= 0) { p.fin = t; return false; } return true; });
  }
  const ciclo = pedidos.map(p => p.fin - p.ini);
  const media = a => a.reduce((x, y) => x + y, 0) / a.length;
  return {
    wip: limiteWip,
    primerEntrega: Math.min(...pedidos.map(p => p.fin)).toFixed(1),
    todoListo: t.toFixed(1),
    cicloMedio: media(ciclo).toFixed(1),
    rendimiento: (12 / t).toFixed(2),
  };
}
console.log('WIP | 1ra entrega (d) | todo listo (d) | ciclo medio (d) | pedidos/día');
for (const w of [12, 6, 3, 1]) {
  const x = simular(w, 7);
  console.log(String(x.wip).padStart(3), '|', x.primerEntrega.padStart(15), '|', x.todoListo.padStart(14), '|', x.cicloMedio.padStart(15), '|', x.rendimiento.padStart(11));
}

// Diez tareas INVENTADAS. Cada una "suele llevar 2 días", pero a veces se complica.
// Duración real: 2 días multiplicados por un factor con cola larga (lognormal, mediana 1).
function azar(semilla) { let s = semilla; return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296); }
const r = azar(42);
function normal() { return Math.sqrt(-2 * Math.log(1 - r())) * Math.cos(2 * Math.PI * r()); }
const tarea = () => 2 * Math.exp(0.6 * normal());
const N = 20000, totales = [];
for (let i = 0; i < N; i++) { let suma = 0; for (let k = 0; k < 10; k++) suma += tarea(); totales.push(suma); }
totales.sort((a, b) => a - b);
const pct = p => totales[Math.floor(p * N)].toFixed(1);
console.log('Estimación sumando lo típico: 10 x 2 = 20 días');
console.log('Terminan en 20 días o menos:', (100 * totales.filter(x => x <= 20).length / N).toFixed(0) + '% de las veces');
console.log('Mediana real:', pct(0.5), 'días | 80 %:', pct(0.8), 'días | 95 %:', pct(0.95), 'días');
